{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "어린이공원이라는 이유만으로 음주 과태료 10만원이 자동 적용되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "어린이공원이라는 이유만으로 음주 과태료 10만원이 자동 적용되지는 않습니다. 서울특별시 도시공원 조례 제22조의3에 따르면 시장은 어린이공원을 금주구역으로 지정할 수 있을 뿐, 어린이공원이라고 해서 자동으로 금주구역이 되는 것은 아닙니다. 금주구역으로 지정된 곳에서 음주를 한 경우에 한해 같은 조례 제23조 제4항에 따라 10만원의 과태료가 부과됩니다.",
          "b_ids": "도시공원:제22조의3, 도시공원:제23조제4항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "금주구역 지정과 과태료 규정 설명",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "금주구역 지정: 서울특별시 도시공원 조례 제22조의3에 따라 시장은 「국민건강증진법」 제8조의4에 근거하여 법 제15조제1항제2호나목의 어린이공원을 금주구역으로 지정할 수 있습니다. 과태료 규정: 같은 조례 제23조 제4항은 시장이 「국민건강증진법」 제8조의4제2항을 위반하여 금주구역에서 음주를 한 사람에게 10만원의 과태료를 부과·징수한다고 정합니다. 또한 제23조 제2항은 위반 정도, 위반 횟수, 위반행위의 동기 및 결과 등을 고려하여 제1항에 따른 과태료 금액의 2분의 1 범위에서 금액을 줄이거나 늘릴 수 있도록 하되, 늘리는 경우에도 법 제56조제1항 및 제2항에 따른 과태료 상한을 초과할 수 없다고 규정합니다.",
          "b_ids": "도시공원:제22조의3, 도시공원:제23조제4항, 도시공원:제23조제2항, 도시공원:제23조제2항단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
